<script setup>
import {ref,reactive,onMounted,onUnmounted,watch} from 'vue';
import {commerceRequest} from './commerce-api';
import SupplierDispatch from './SupplierDispatch.vue';
import OrderMessage from './OrderMessage.vue';
import DigitalDownloads from './DigitalDownloads.vue';
import {customerShipments,hasCurrentMessage} from './order-mail.js';
const props=defineProps({endpoint:String,token:String,connected:Boolean,refreshKey:Number});
const orders=ref([]),inventory=ref([]),busy=ref(false),error=ref(''),message=ref(''),view=ref('all'),status=ref('all');
const nextCursor=ref(''),total=ref(0),summary=ref({}),search=ref(''),dateFrom=ref(''),dateTo=ref(''),exportKind=ref('orders');
const drafts=reactive({});
const pricingHolds=ref([]);
async function clearPricingHold(id){if(!confirm('Publish your reviewed retail price first. Clear this purchase suspension? Paid orders still require review.'))return;await request('/admin/fulfillment-holds/'+encodeURIComponent(id),{action:'clear'});await refresh();}
const messageComposer=ref(null);
const lanes=[['all','All orders','01','Every checkout, including automated fulfillment.','▤'],['inbox','Needs your action','02','Orders waiting for you to order or ship.','↘'],['progress','Processing','03','Ordered, being made, or getting packed.','↗'],['shipped','Shipped','04','Tracking saved. Time for a thank-you.','✓']];
function journey(order){const fs=order.fulfillments || [];return {processing:fs.length>0&&fs.every(f=>['submitted','sending-to-production','in-production','fulfilled','shipped','delivered'].includes(f.state)),shipped:fs.length>0&&fs.every(f=>['shipped','delivered','canceled'].includes(f.state))};}
const names={keycaps:'Custom keycaps',aliexpress:'AliExpress',mouser:'Mouser',office:'RODDY shipment',printify:'Printify'};
const ready=f=>['ready-to-order','awaiting-submission','ready-to-ship'].includes(f.state);
const label=f=>ready(f)?f.kind==='office'?'Ready to ship':'Place supplier order':f.state==='submitted'?'Ordered · waiting for dispatch':f.state==='shipped'?'Shipped':f.state.replaceAll('-',' ');
function afterCosts(order){return order.finance?.netAfterFees!=null && order.expenses?.length && order.expenses.every(e=>e.currency==='USD') ? order.finance.netAfterFees-order.expenses.reduce((n,e)=>n+e.amount,0) : null;}
const money=(n,currency='USD')=>new Intl.NumberFormat('en-US',{style:'currency',currency}).format((n || 0)/100);
const date=n=>new Date(n*1000).toLocaleString(undefined,{year:'numeric',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
const request=(path,body)=>commerceRequest(props.endpoint,path,props.token,body);
function filters(){return {view:view.value,status:status.value,search:search.value,start:dateFrom.value?Math.floor(new Date(dateFrom.value+'T00:00:00').getTime()/1000):0,end:dateTo.value?Math.floor(new Date(dateTo.value+'T00:00:00').getTime()/1000)+86400:0};}
let refreshSequence=0,refreshTimer=null,backgroundLoading=false;
const lastUpdated=ref(null);
async function refresh(preservePages=false){
  const sequence=++refreshSequence,query=filters(),wanted=preservePages?orders.value.length:0;
  const data=await request('/admin/orders?'+new URLSearchParams(query));
  const rows=[...data.data];let cursor=data.next_cursor || '';
  while(cursor && rows.length<wanted){
    if(sequence!==refreshSequence)return;
    const page=await request('/admin/orders?'+new URLSearchParams({...query,cursor}));
    rows.push(...page.data);cursor=page.next_cursor || '';
  }
  if(sequence!==refreshSequence)return;
  orders.value=rows;nextCursor.value=cursor;total.value=data.total ?? rows.length;
  summary.value=data.summary || {};lastUpdated.value=new Date();
  const holds=await request('/admin/fulfillment-holds');if(sequence===refreshSequence)pricingHolds.value=holds.items || [];
}
async function autoRefresh(){
  if(!props.connected || busy.value || backgroundLoading || document.hidden)return;
  backgroundLoading=true;
  try{await refresh(true);error.value='';}catch(e){error.value='Orders could not refresh: '+e.message;}
  finally{backgroundLoading=false;}
}
function showAll(){view.value='all';status.value='all';search.value='';dateFrom.value='';dateTo.value='';load();}

async function run(fn){busy.value=true;error.value='';message.value='';try{await fn();}catch(e){error.value=e.message;}finally{busy.value=false;}}
const load=()=>run(refresh);
function lane(id){view.value=id;status.value='all';load();}
function more(){return run(async()=>{refreshSequence++;const data=await request('/admin/orders?'+new URLSearchParams({...filters(),cursor:nextCursor.value}));orders.value.push(...data.data);nextCursor.value=data.next_cursor || '';});}
async function download(path,filename,body={}){const response=await fetch(props.endpoint.replace(/\/$/,'')+path,{method:'POST',headers:{'content-type':'application/json',authorization:'Bearer '+props.token},body:JSON.stringify(body)});if(!response.ok)throw new Error((await response.json()).error || 'Download failed.');const url=URL.createObjectURL(await response.blob());const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function packet(order,kind){return run(()=>download('/admin/orders/'+order.id+(kind==='keycaps'?'/keycaps':'/supplier'),'RODDY-'+order.id+'-'+kind+'.zip',{action:'download',kind}));}
function pendingPackets(){return run(()=>download('/admin/keycaps/packets','RODDY-pending-keycap-orders.zip'));}
function exportRecords(){return run(()=>download('/admin/orders/export','RODDY-'+exportKind.value+'.csv',{...filters(),view:'all',kind:exportKind.value}));}
function syncRecords(){return run(async()=>{let cursor='',checked=0;do{const data=await request('/admin/orders/sync',{...filters(),cursor});checked+=data.checked;cursor=data.next_cursor || '';}while(cursor);await refresh();message.value=checked+' payment records checked with Square.';});}
function orderDraft(order,kind){const fulfillment=order.fulfillments.find(f=>f.kind===kind),tracking=fulfillment?.shipments?.at(-1);return drafts[order.id+':'+kind] ||= {reference:fulfillment?.supplierId || '',amount:'',carrier:tracking?.carrier || '',number:tracking?.number || '',url:tracking?.url || ''};}
async function invoice(order,kind,ref,amount){if(!amount)return;await request('/admin/orders/'+order.id+'/expenses',{supplier:names[kind],reference:ref,amountCents:Math.round(Number(amount)*100),currency:'USD',date:new Date().toLocaleDateString('en-CA'),note:''});}
function ordered(order,kind){return run(async()=>{const d=orderDraft(order,kind);if(!d.reference.trim())throw new Error('Add the supplier order number so you can find it later.');await request('/admin/orders/'+order.id+(kind==='keycaps'?'/keycaps':'/supplier'),{action:kind==='keycaps'?'submitted':'ordered',kind,supplierReference:d.reference});try{await invoice(order,kind,d.reference,d.amount);}finally{await refresh();}message.value='Ordered ✓ Next stop: dispatch and tracking.';});}
function pending(order,kind){return run(async()=>{await request('/admin/orders/'+order.id+(kind==='keycaps'?'/keycaps':'/supplier'),{action:'pending',kind});await refresh();message.value='Back in your inbox.';});}
function shipment(order,kind){return run(async()=>{const d=orderDraft(order,kind);await request('/admin/orders/'+order.id+'/shipment',{kind,carrier:d.carrier,number:d.number,url:d.url});await refresh();message.value='On its way ✓ Tracking saved. Your thank-you draft is ready.';const latest=await request('/admin/orders?view=all&search='+encodeURIComponent(order.id));const updated=latest.data.find(o=>o.id===order.id);if(updated)await messageComposer.value.open(updated);});}
function messageRecorded(){refresh().then(()=>{message.value='Thank-you marked sent ✓ A copy is saved with the order.';}).catch(e=>{error.value=e.message;});}
function reconcile(order){return run(async()=>{await request('/admin/orders/'+order.id+'/reconcile',{});await refresh();});}
function cancel(order){return run(async()=>{await request('/admin/orders/'+order.id+'/cancel',{});await refresh();message.value='Unpaid checkout canceled.';});}
function addressText(a){return a?[a.first_name+' '+a.last_name,a.address1,a.address2,a.city+', '+a.region+' '+a.zip,a.country,a.phone,a.email].filter(Boolean).join('\n'):'';}
function copy(value){return run(async()=>{await navigator.clipboard.writeText(value);message.value='Copied. Ready to paste.';});}
function expenseDraft(order){return drafts['expense:'+order.id] ||= {supplier:'',reference:'',amount:'',date:new Date().toLocaleDateString('en-CA'),note:''};}
function addExpense(order){return run(async()=>{const d=expenseDraft(order);await request('/admin/orders/'+order.id+'/expenses',{...d,amountCents:Math.round(Number(d.amount)*100),currency:'USD'});delete drafts['expense:'+order.id];await refresh();message.value='Invoice recorded ✓';});}
function loadInventory(){return run(async()=>{const data=await request('/admin/inventory');inventory.value=data.items;for(const i of inventory.value)drafts['stock:'+i.id]=i.stock;});}
function stock(item){return run(async()=>{await request('/admin/inventory/'+encodeURIComponent(item.id),{stock:Number(drafts['stock:'+item.id])});const data=await request('/admin/inventory');inventory.value=data.items;message.value='Stock saved.';});}
watch(()=>props.refreshKey,()=>{if(props.connected)load();});
watch(()=>props.connected,connected=>{if(connected)load();else{refreshSequence++;orders.value=[];inventory.value=[];summary.value={};lastUpdated.value=null;}});
onMounted(()=>{if(props.connected)load();refreshTimer=setInterval(autoRefresh,30000);});
onUnmounted(()=>{refreshSequence++;clearInterval(refreshTimer);});
</script>
<template>
  <section class="order-manager">
    <header class="order-desk-heading"><div><p class="desk-eyebrow">RODDY / ORDER DESK <span class="live-dot" /></p><h2>LET’S GET THESE MOVING<span>.</span></h2><p>Every order stays here, including automatic supplier fulfillment, downloads, and manual shipments.</p></div><div class="desk-stamp" aria-hidden="true">PACK IT.<br />SHIP IT.<br /><span>MAKE THEIR DAY.</span></div></header>
    <nav class="order-flow" aria-label="Order workflow"><button v-for="[id,title,step,help,icon] in lanes" :key="id" :class="id" :aria-pressed="view===id" :disabled="busy" @click="lane(id)"><span class="flow-top"><small>{{step}} / {{title}}</small><b aria-hidden="true">{{icon}}</b></span><strong>{{summary[id] || 0}}</strong><span class="flow-help">{{help}}</span></button></nav>
    <div class="order-tools"><div class="secondary-views"><button :aria-pressed="view==='attention'" :disabled="busy" @click="lane('attention')">Needs attention <b>{{summary.attention || 0}}</b></button><button :disabled="busy" @click="showAll">Show all / clear filters</button><button :aria-pressed="view==='free'" :disabled="busy" @click="lane('free')">Free download orders <b>{{summary.free || 0}}</b></button><button :disabled="busy || !connected" @click="load">{{busy?'Working…':'Refresh ↻'}}</button></div><p class="sales-tally">RECORDED SALES <strong>{{money(summary.capturedCents)}}</strong><span v-if="summary.refundedCents"> · {{money(summary.refundedCents)}} refunded</span></p></div>
    <p v-if="!connected" class="notice">Connect your GitHub owner account to load private order history.</p>
    <p v-else class="order-refresh-status" role="status">{{lastUpdated?'Updated '+lastUpdated.toLocaleTimeString():'Loading order history…'}} · Refreshes every 30 seconds while this page is visible.</p>
    <p v-if="summary.free" class="order-refresh-status">{{summary.free}} free download orders · {{summary.freeStarted || 0}} opened a download link. Free orders add $0 to recorded sales.</p>
    <div class="order-search"><input v-model="search" type="search" aria-label="Search orders" placeholder="Find an order, reference or customer…" @keydown.enter="load" /><button class="button small" :disabled="busy" @click="load">Find →</button><label>Payment<select v-model="status" aria-label="Payment status" @change="load"><option value="all">All statuses</option><option value="paid">Paid</option><option value="free">Free downloads · $0</option><option value="refunded">Refunded</option><option value="partially-refunded">Partially refunded</option><option value="unconfirmed">Unconfirmed</option><option value="canceled">Canceled</option><option value="processing">Processing</option><option value="failed">Failed</option></select></label></div>
    <p v-if="error" class="notice" role="alert">{{error}}</p><p v-if="message" class="desk-success" role="status">{{message}}</p>
    <div class="order-cards"><article v-for="order in orders" :key="order.id" class="order-card" :class="{unpaid:!['paid','free'].includes(order.payment_status),dispatched:journey(order).shipped}">
      <header class="order-card-heading"><div><button class="order-number" title="Copy full order reference" @click="copy('RODDY-'+order.id)">#{{order.id.slice(-8).toUpperCase()}} ↗</button><p>{{date(order.created)}} <span v-if="order.address">· {{order.address.first_name}} {{order.address.last_name}}</span></p></div><div class="order-total"><strong>{{money(order.amount_total)}}</strong><span class="payment-chip" :class="order.payment_status">{{order.payment_status.replaceAll('-',' ')}}</span></div></header>
      <ul class="order-items"><li v-for="(item,index) in order.items" :key="index"><b class="quantity-pill">{{item.qty}}×</b><div><strong>{{item.name}}</strong><details v-if="item.label"><summary>Design / options</summary><p>{{item.label}}</p></details><p v-if="item.supplier" class="supplier-part">{{names[item.kind]}} · {{item.supplier.supplierSku}}<span v-if="item.supplier.variantId"> · SKU {{item.supplier.variantId}}</span><a v-if="item.supplier.productUrl?.startsWith('https://')" :href="item.supplier.productUrl" target="_blank" rel="noopener noreferrer">Open exact listing ↗</a></p><details v-if="item.supplier?.bom"><summary>Parts kit · {{item.supplier.bom.revision}} · frozen order BOM</summary><ul><li v-for="line in item.supplier.bom.lines" :key="line.supplierSku">{{line.quantity * item.qty}} × {{line.supplierSku}}<span v-if="line.note"> · {{line.note}}</span></li></ul><p class="small-help">Quantities are supplier order units for this order, including any packs. Matching hardware bundles ship separately from RODDY.</p></details></div></li></ul>
      <ol v-if="order.payment_status==='paid'&&order.fulfillments.length" class="order-journey" aria-label="Order progress"><li class="complete">Received <span>✓</span></li><li :class="{complete:journey(order).processing}">Processed <span>{{journey(order).processing?'✓':'·'}}</span></li><li :class="{complete:journey(order).shipped}">Shipped <span>{{journey(order).shipped?'✓':'·'}}</span></li><li :class="{complete:hasCurrentMessage(order)}">Thanked <span>{{hasCurrentMessage(order)?'✓':'·'}}</span></li></ol>
      <div v-if="order.address?.address1" class="delivery-card"><div><small>SHIP TO</small><address>{{order.address.first_name}} {{order.address.last_name}}<br />{{order.address.address1}} {{order.address.address2}}<br />{{order.address.city}}, {{order.address.region}} {{order.address.zip}} · {{order.address.country}}</address><p>{{order.address.email}} · {{order.address.phone}}</p></div><button type="button" :disabled="busy" @click="copy(addressText(order.address))">Copy address ⧉</button></div>
      <div v-else-if="order.address?.email" class="delivery-card"><div><small>CUSTOMER EMAIL</small><p>{{order.address.email}}</p><p v-if="order.payment_status==='free'">{{order.downloadOpenedAt?'Download opened '+date(order.downloadOpenedAt):'Free download requested'}} · {{order.address.newsletter_consent?'Email updates requested':'Download and support only'}}</p></div><button type="button" :disabled="busy" @click="copy(order.address.email)">Copy email ⧉</button></div>
      <section v-for="f in order.fulfillments" :key="f.kind" class="fulfillment-step"><div class="step-heading"><strong>{{names[f.kind] || f.kind}}</strong><span class="step-chip" :class="{done:['shipped','delivered'].includes(f.state),next:ready(f)}">{{label(f)}}</span></div><p v-if="f.automatic || f.kind==='printify'" class="small-help">Automatic fulfillment · Updated {{date(f.updated)}}</p><p v-if="f.error" class="notice">{{f.error}}</p><p v-if="f.supplierId" class="supplier-reference">Supplier reference: {{f.supplierId}}</p>
        <template v-if="order.payment_status==='paid'"><SupplierDispatch v-if="!f.automatic && ['keycaps','aliexpress','mouser'].includes(f.kind)" :endpoint="endpoint" :token="token" :kind="f.kind" :reference="order.id" />
          <div v-if="!f.automatic && ['keycaps','aliexpress','mouser'].includes(f.kind) && ready(f)" class="next-action"><p class="step-caption">01 / PLACE THE ORDER</p><button class="button primary small" :disabled="busy" @click="packet(order,f.kind)">{{f.kind==='keycaps'?'Download design JSON & order details ↓':'Download supplier order details ↓'}}</button><p v-if="f.kind==='keycaps'" class="small-help">Includes the design, quantity and delivery details.</p><form class="order-confirm-form" @submit.prevent="ordered(order,f.kind)"><label>Supplier order number<input v-model="orderDraft(order,f.kind).reference" maxlength="150" placeholder="Paste the reference after ordering" required /></label><label>Actual supplier total · USD <small>optional</small><input v-model="orderDraft(order,f.kind).amount" type="number" min="0.01" step="0.01" placeholder="Invoice total" /></label><button class="button small" :disabled="busy">Mark ordered ✓</button></form></div>
          <p v-if="f.kind==='mouser' && f.automatic" class="small-help">Supplier status and tracking sync automatically. Ambiguous submissions stay under review; they are never resubmitted blindly. <a href="https://www.mouser.com/en/account/orders" target="_blank" rel="noopener noreferrer">Open Mouser orders ↗</a></p><div v-if="f.kind==='printify'" class="printify-actions"><a class="button small" href="https://printify.com/app/orders" target="_blank" rel="noopener noreferrer">Open production orders ↗</a><button v-if="f.state==='review'" class="button small" :disabled="busy" @click="reconcile(order)">Find existing production order</button></div>
          <details v-if="!f.automatic && ['office','keycaps','aliexpress','mouser'].includes(f.kind) && (!ready(f) || f.kind==='office')" class="tracking-editor" :open="f.state!=='shipped'"><summary>{{f.state==='shipped'?'Update tracking':'02 / SEND IT ON ITS WAY'}}</summary><form class="form-grid" @submit.prevent="shipment(order,f.kind)"><label>Carrier<input v-model="orderDraft(order,f.kind).carrier" placeholder="USPS, UPS, DHL…" required /></label><label>Tracking number<input v-model="orderDraft(order,f.kind).number" required /></label><label class="full">Tracking link <small>optional</small><input v-model="orderDraft(order,f.kind).url" type="url" /></label><button class="button primary small" :disabled="busy">Save tracking + mark shipped ✓</button></form></details>
          <button v-if="!f.automatic && f.state==='submitted' && ['keycaps','aliexpress','mouser'].includes(f.kind)" class="undo-action" :disabled="busy" @click="pending(order,f.kind)">Undo: back to inbox</button>
        </template>
        <div v-for="shipment in f.shipments" :key="shipment.number" class="tracking-receipt"><b>↗ {{shipment.carrier}}</b><span>{{shipment.number}}</span><a v-if="shipment.url" :href="shipment.url" target="_blank" rel="noopener noreferrer">Track package →</a></div>
      </section>
      <DigitalDownloads v-if="['paid','free'].includes(order.payment_status) && order.items.some(i=>['digital','free-digital'].includes(i.kind))" :order="order" :endpoint="endpoint" :token="token" :disabled="busy" />
      <section v-if="['paid','free'].includes(order.payment_status)" class="customer-sendoff"><div><p class="step-caption">04 / MAKE THEIR DAY</p><h3>{{hasCurrentMessage(order)?'Thank-you sent. Nice touch.':customerShipments(order).length?'Tracking ready. Add a little thanks.':'Make it personal.'}}</h3><p>{{hasCurrentMessage(order)?'Your sent confirmation is saved with this order.':customerShipments(order).length?'A warm thank-you, with their tracking already filled in.':'Send a thank-you now, or come back when it ships.'}}</p></div><button class="button small" :disabled="busy||!order.address?.email" @click="messageComposer.open(order)">{{hasCurrentMessage(order)?'Write another message ↗':customerShipments(order).length?'Thank-you + tracking ↗':'Write a thank-you ↗'}}</button><details v-if="order.messages?.length" class="contact-history"><summary>Contact history · {{order.messages.length}}</summary><div v-for="note in order.messages" :key="note.id"><strong>{{note.subject}}</strong><p>Marked sent by you · {{date(note.created)}} · {{note.recipient}}</p><pre>{{note.body}}</pre></div></details></section>
      <button v-if="order.payment_status==='unconfirmed'" class="undo-action" :disabled="busy" @click="cancel(order)">Cancel unpaid checkout</button>
      <details class="order-accounting"><summary>Payment & invoice records</summary><p v-if="order.finance">Captured {{money(order.finance.captured)}} · Refunded {{money(order.finance.refunded)}} · Fees {{order.finance.fees===null?'not yet reported':money(order.finance.fees)}}<span v-if="order.finance.netAfterFees!==null"> · Net {{money(order.finance.netAfterFees)}}</span></p><p v-if="afterCosts(order)!==null"><strong>Remaining after recorded supplier costs: {{money(afterCosts(order))}}</strong><br /><small>Includes reported payment fees; excludes costs not yet recorded.</small></p><p>Square reference: {{order.providerId || 'Not created'}}</p><p v-for="expense in order.expenses || []" :key="expense.id">{{expense.incurred}} · {{expense.supplier}} · {{expense.reference}} · {{money(expense.amount,expense.currency)}}<small v-if="expense.note"><br />{{expense.note}}</small></p><details><summary>Add a supplier invoice</summary><form class="form-grid" @submit.prevent="addExpense(order)"><label>Supplier<input v-model="expenseDraft(order).supplier" required /></label><label>Invoice reference<input v-model="expenseDraft(order).reference" required /></label><label>Invoice date<input v-model="expenseDraft(order).date" type="date" required /></label><label>Actual total · USD<input v-model="expenseDraft(order).amount" type="number" min="0.01" step="0.01" required /></label><label class="full">Note<input v-model="expenseDraft(order).note" maxlength="500" /></label><button class="button small" :disabled="busy">Record invoice</button></form></details></details>
    </article></div>
    <section v-if="pricingHolds.length" class="desk-reports"><h3>Purchasing suspended · pricing review</h3><p class="small-help">Shared controls for Printify, Mouser, and future AliExpress/Yuzu automation. Update and publish the retail price before clearing a hold. Existing paid orders keep their original price.</p><div v-for="hold in pricingHolds" :key="hold.product"><strong>{{hold.product}} · {{names[hold.provider] || hold.provider}}</strong><p>{{hold.reason}}</p><button class="button small" :disabled="busy" @click="clearPricingHold(hold.product).catch(e=>error=e.message)">Price reviewed · allow new purchases</button></div></section><div v-if="connected && !orders.length && !busy && !error" class="order-empty"><h3>{{view==='inbox'?'No manual actions waiting.':'No orders match this view.'}}</h3><p>{{view==='inbox'?'Automated orders remain visible in All orders and Processing.':'Clear your filters to see the complete order history.'}}</p><button class="button small" @click="showAll">Show all orders</button></div>
    <button v-if="nextCursor" class="button small" :disabled="busy" @click="more">Load more orders ↓</button><p class="loaded-count">{{orders.length}} of {{total}} matching orders</p>
    <OrderMessage ref="messageComposer" :endpoint="endpoint" :token="token" @recorded="messageRecorded" />
    <details class="desk-reports"><summary>Reports, CSV exports & tools ↗</summary><div class="form-grid"><label>From<input v-model="dateFrom" type="date" /></label><label>Through<input v-model="dateTo" type="date" /></label><button class="button small" :disabled="busy" @click="load">Apply dates</button><label>Export<select v-model="exportKind"><option value="orders">Order summary</option><option value="items">Line items</option><option value="expenses">Supplier expenses</option><option value="payments">Payment history</option></select></label><button class="button small" :disabled="busy || !connected" @click="exportRecords">Download CSV ↓</button><button class="button small" :disabled="busy || !connected" @click="syncRecords">Refresh payment records</button><button class="button small" :disabled="busy || !connected" @click="pendingPackets">Download next 100 keycap packets ↓</button><a class="button small" href="https://squareup.com/dashboard/sales/transactions" target="_blank" rel="noopener noreferrer">Square receipts & refunds ↗</a></div><p class="small-help">CSV exports include every matching order, with UTC timestamps. Blank fees or tax have not been verified. Exports cover all workflow stages using your dates, search and payment filter. Supplier expenses use their invoice currency.</p></details>
    <details class="desk-reports" @toggle="e=>{if(e.target.open && !inventory.length)loadInventory()}"><summary>Stock you ship from RODDY</summary><div class="product-table-wrap"><table class="admin-table"><thead><tr><th>Product</th><th>Available</th><th>Reserved</th><th>On hand</th><th /></tr></thead><tbody><tr v-for="item in inventory" :key="item.id"><td>{{item.name}}</td><td>{{item.available}}</td><td>{{item.reserved}}</td><td><input v-model="drafts['stock:'+item.id]" type="number" min="0" :aria-label="`On-hand stock for ${item.name}`" /></td><td><button class="button small" :disabled="busy" @click="stock(item)">Save stock</button></td></tr></tbody></table></div></details>
  </section>
